      role: "Ingeniero de backend",
      status: 'completed',
      relevance: "Corrección bajo concurrencia, demostrada con tests: idempotencia, bloqueos sin deadlocks, invariantes que se sostienen bajo carga y eventos confiables con un outbox.",
      startDate: '2026-11',
